"use client";

import React from 'react';
import { Landmark, Receipt, Percent, DollarSign, ArrowUpRight } from 'lucide-react';
import { Transaction, Payout } from '../types';

interface FinanceStatsGridProps {
  transactions: Transaction[];
  payouts: Payout[];
}

export default function FinanceStatsGrid({ transactions, payouts }: FinanceStatsGridProps) {
  const totalVolume = transactions.reduce((sum, t) => sum + t.amount, 0) + 6350000;
  const platformFees = totalVolume * 0.18;
  const resaleComms = 41280;
  const netPlatformProfit = platformFees + resaleComms;
  const totalPaidOut = payouts.filter(p => p.status === 'Processed').reduce((sum, p) => sum + p.amount, 0) + 4200000;
  const pendingPayoutsTotal = payouts.filter(p => p.status === 'Pending').reduce((sum, p) => sum + p.amount, 0);

  return (
    <div className="grid gap-4 grid-cols-1 md:grid-cols-4">
      {/* Gross Volume */}
      <div className="rounded-2xl border border-slate-800 bg-slate-950 p-4.5">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500 uppercase tracking-wider">Gross Sales Flow</span>
          <Landmark className="h-4 w-4 text-indigo-400" />
        </div>
        <p className="mt-2 text-2xl font-bold text-white">${totalVolume.toLocaleString()}</p>
        <span className="mt-1 block text-3xs text-emerald-400 font-semibold flex items-center gap-0.5">
          <ArrowUpRight className="h-3 w-3" /> +18.2% vs last cycle
        </span>
      </div>

      {/* Settled wire payouts */}
      <div className="rounded-2xl border border-slate-800 bg-slate-950 p-4.5">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500 uppercase tracking-wider">Settled Wire Payouts</span>
          <Receipt className="h-4 w-4 text-emerald-400" />
        </div>
        <p className="mt-2 text-2xl font-bold text-white">${totalPaidOut.toLocaleString()}</p>
        <span className="mt-1 block text-3xs text-slate-500">
          Wire settlements processed securely
        </span>
      </div>

      {/* Net platform profit */}
      <div className="rounded-2xl border border-slate-800 bg-slate-950 p-4.5">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500 uppercase tracking-wider">Net Platform Profit</span>
          <Percent className="h-4 w-4 text-pink-400" />
        </div>
        <p className="mt-2 text-2xl font-bold text-white">${netPlatformProfit.toLocaleString()}</p>
        <span className="mt-1 block text-3xs text-emerald-400 font-semibold flex items-center gap-0.5">
          <ArrowUpRight className="h-3 w-3" /> 18% fee + 10% resale splits
        </span>
      </div>

      {/* Pending wire escrow */}
      <div className="rounded-2xl border border-slate-800 bg-slate-950 p-4.5">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium text-slate-500 uppercase tracking-wider">Wire Escrow Backlog</span>
          <DollarSign className="h-4 w-4 text-amber-400" />
        </div>
        <p className="mt-2 text-2xl font-bold text-white">${pendingPayoutsTotal.toLocaleString()}</p>
        <span className="mt-1 block text-3xs text-amber-400 animate-pulse font-semibold">
          Compliance wire validation pending
        </span>
      </div>
    </div>
  );
}
